<script setup>
import {computed,onMounted,ref} from 'vue'
import {ArrowDown,ArrowUp,BookOpen,ClipboardList,FileText,Plus} from '@lucide/vue'
import {useRoute} from 'vue-router'
import {api} from '../api'
import {activityLocation} from '../utils/courseActivityNavigation'
import CourseTools from '../components/CourseTools.vue'
import UnitAssessmentCreator from '../components/UnitAssessmentCreator.vue'
const route=useRoute(),course=ref(null),unit=ref(null),units=ref([]),busy=ref(false),error=ref(''),notice=ref(''),creator=ref('')
const courseId=computed(()=>String(route.params.courseId)),unitId=computed(()=>String(route.params.unitId))
const staff=computed(()=>['teacher','ta'].includes(course.value?.courseRole))
const canCreateMaterials=computed(()=>staff.value&&course.value?.status!=='archived'&&!course.value?.taRestrictions?.includes('materials'))
const canCreateAssessments=computed(()=>staff.value&&course.value?.status!=='archived'&&!course.value?.taRestrictions?.includes('assessments'))
const icons={material:BookOpen,quiz:ClipboardList,assignment:FileText,report:FileText},labels={material:'教材',quiz:'線上測驗',assignment:'線上作業',report:'PDF 作業'}
async function load(){busy.value=true;error.value='';try{const [detail,courseData,curriculum]=await Promise.all([api(`/courses/${courseId.value}/units/${unitId.value}`),api(`/courses/${courseId.value}`),api(`/courses/${courseId.value}/curriculum`)]);unit.value=detail;course.value=courseData;units.value=curriculum.units||[]}catch(e){error.value=e.message}finally{busy.value=false}}
async function move(index,direction){const items=[...unit.value.activities],target=index+direction;[items[index],items[target]]=[items[target],items[index]];busy.value=true;error.value='';try{await api(`/courses/${courseId.value}/units/${unitId.value}/activities/reorder`,{method:'PUT',body:{items:items.map(({kind,id})=>({kind,id}))}});unit.value.activities=items;notice.value='活動順序已更新。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function moveUnit(item,event){busy.value=true;error.value='';try{await api(`/courses/${courseId.value}/units/activities/${item.kind}/${item.id}`,{method:'PUT',body:{unitId:event.target.value}});notice.value='活動已移至指定單元。';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><RouterLink :to="`/courses/${courseId}`" class="back-link">← 返回課程內容</RouterLink><p v-if="error" class="error-box" role="alert">{{error}}</p><p v-if="notice" class="success-box" role="status">{{notice}}</p><p v-if="busy&&!unit">載入單元中…</p><template v-if="unit"><section class="page-heading"><div><p class="eyebrow">UNIT {{unit.sortOrder}}</p><h1>{{unit.name}}</h1><p class="muted">{{unit.description||'依序完成本單元的教材與評量。'}}</p></div></section><div v-if="canCreateMaterials||canCreateAssessments" class="unit-create-actions"><button v-if="canCreateMaterials" class="button primary" @click="creator=creator==='material'?'':'material'"><Plus :size="16"/>新增教材</button><button v-if="canCreateAssessments" class="button secondary" @click="creator=creator==='assessment'?'':'assessment'"><Plus :size="16"/>新增測驗／作業</button></div><CourseTools v-if="creator==='material'&&course" :course="course" staff section="resources" :locked-unit-id="unitId" @changed="load"/><section v-if="creator==='assessment'&&course" class="surface form-surface"><UnitAssessmentCreator :course="course" :unit-id="unitId"/></section><section class="surface unit-workspace"><div class="section-title"><div><h2>單元活動</h2><p>教材、作業與測驗依學生看到的順序排列。</p></div></div><ol class="unit-path"><li v-for="(item,index) in unit.activities" :key="`${item.kind}:${item.id}`"><component :is="icons[item.kind]" :size="19"/><div><small>{{labels[item.kind]}} · {{item.status==='draft'?'草稿':item.status==='closed'?'已關閉':'可使用'}}</small><RouterLink :to="activityLocation(courseId,item)">{{item.title}}</RouterLink><span v-if="item.dueAt" class="muted">截止 {{new Date(item.dueAt).toLocaleString()}}</span></div><div v-if="unit.canManage" class="activity-order"><button class="icon-button" :aria-label="`${item.title} 上移`" :disabled="busy||index===0" @click="move(index,-1)"><ArrowUp :size="17"/></button><button class="icon-button" :aria-label="`${item.title} 下移`" :disabled="busy||index===unit.activities.length-1" @click="move(index,1)"><ArrowDown :size="17"/></button><select :aria-label="`${item.title} 所屬單元`" :value="item.unitId" :disabled="busy" @change="moveUnit(item,$event)"><option v-for="choice in units" :key="choice.id" :value="choice.id">{{choice.name}}</option></select></div></li></ol><p v-if="!unit.activities.length" class="empty-inline">此單元尚無教學活動。</p></section></template></template>
<style scoped>.unit-create-actions{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:18px}.unit-workspace{padding:22px}.unit-path{list-style:none;padding:0;margin:0}.unit-path li{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:12px;align-items:center;padding:15px 0;border-top:1px solid var(--line)}.unit-path li>div:nth-child(2){display:grid;gap:3px}.unit-path small{color:var(--muted)}.unit-path a{font-weight:700}.activity-order{display:flex;gap:3px}@media(max-width:650px){.unit-path li{grid-template-columns:auto minmax(0,1fr)}.activity-order{grid-column:2}}</style>
